export declare const schema = "\nCREATE TABLE IF NOT EXISTS sessions (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  model TEXT NOT NULL DEFAULT 'z-ai/glm-5.2',\n  user_id TEXT,\n  project_id TEXT,\n  summary_text TEXT DEFAULT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS messages (\n  id TEXT PRIMARY KEY,\n  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,\n  role TEXT NOT NULL,\n  content TEXT,\n  tool_calls TEXT,\n  tool_call_id TEXT,\n  step_number INTEGER,\n  user_id TEXT,\n  is_compacted INTEGER DEFAULT 0,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS tasks (\n  id TEXT PRIMARY KEY,\n  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,\n  description TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending',\n  model TEXT,\n  max_steps INTEGER DEFAULT 100,\n  current_step INTEGER DEFAULT 0,\n  result TEXT,\n  error TEXT,\n  user_id TEXT,\n  workspace_dir TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS agent_steps (\n  id TEXT PRIMARY KEY,\n  task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,\n  step_number INTEGER NOT NULL,\n  tool_name TEXT,\n  tool_input TEXT,\n  tool_output TEXT,\n  reasoning TEXT,\n  duration_ms INTEGER,\n  status TEXT DEFAULT 'success',\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS config (\n  key TEXT PRIMARY KEY,\n  value TEXT NOT NULL,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS users (\n  id TEXT PRIMARY KEY,\n  username TEXT NOT NULL UNIQUE,\n  email TEXT,\n  password_hash TEXT NOT NULL,\n  role TEXT NOT NULL DEFAULT 'user',\n  credits INTEGER NOT NULL DEFAULT 0,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS auth_sessions (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  refresh_token_hash TEXT NOT NULL,\n  expires_at DATETIME NOT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS credit_transactions (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  amount INTEGER NOT NULL,\n  balance_after INTEGER NOT NULL,\n  type TEXT NOT NULL,\n  description TEXT,\n  task_id TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS pix_payments (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  provider_payment_id TEXT UNIQUE,\n  status TEXT NOT NULL DEFAULT 'pending',\n  credits INTEGER NOT NULL,\n  amount_brl REAL NOT NULL,\n  qr_code TEXT,\n  qr_code_base64 TEXT,\n  ticket_url TEXT,\n  credited_at DATETIME DEFAULT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS projects (\n  id TEXT PRIMARY KEY,\n  uuid TEXT NOT NULL UNIQUE,\n  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  folder_path TEXT NOT NULL,\n  type TEXT NOT NULL DEFAULT 'static',\n  port INTEGER,\n  pid INTEGER,\n  status TEXT NOT NULL DEFAULT 'active',\n  session_id TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS model_config (\n  id TEXT PRIMARY KEY,\n  model_id TEXT NOT NULL UNIQUE,\n  enabled INTEGER NOT NULL DEFAULT 1,\n  cost_per_step REAL NOT NULL DEFAULT 1,\n  display_name TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS orchestrator_sessions (\n  id TEXT PRIMARY KEY,\n  session_id TEXT DEFAULT NULL REFERENCES sessions(id) ON DELETE SET NULL,\n  user_id TEXT,\n  status TEXT NOT NULL DEFAULT 'idle',\n  objective TEXT NOT NULL,\n  current_step TEXT DEFAULT NULL,\n  progress_percent INTEGER DEFAULT 0,\n  error_count INTEGER DEFAULT 0,\n  auto_recover INTEGER DEFAULT 1,\n  workspace_dir TEXT DEFAULT NULL,\n  md_files TEXT DEFAULT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS orchestrator_steps (\n  id TEXT PRIMARY KEY,\n  orchestrator_session_id TEXT NOT NULL REFERENCES orchestrator_sessions(id) ON DELETE CASCADE,\n  step_number INTEGER NOT NULL,\n  role TEXT NOT NULL,\n  model TEXT NOT NULL,\n  action TEXT NOT NULL,\n  input TEXT NOT NULL,\n  output TEXT,\n  status TEXT NOT NULL DEFAULT 'pending',\n  error_message TEXT DEFAULT NULL,\n  duration_ms INTEGER DEFAULT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  completed_at DATETIME DEFAULT NULL\n);\n\nCREATE TABLE IF NOT EXISTS orchestrator_state (\n  id TEXT PRIMARY KEY DEFAULT 'singleton',\n  is_running INTEGER DEFAULT 0,\n  last_heartbeat DATETIME DEFAULT CURRENT_TIMESTAMP,\n  current_session_id TEXT DEFAULT NULL REFERENCES orchestrator_sessions(id),\n  total_steps_completed INTEGER DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS orchestrator_tasks (\n  id TEXT PRIMARY KEY,\n  orchestrator_session_id TEXT NOT NULL REFERENCES orchestrator_sessions(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  description TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending',\n  role TEXT NOT NULL DEFAULT 'programador',\n  depends_on TEXT,\n  result_json TEXT,\n  output TEXT,\n  error_message TEXT,\n  step_number INTEGER NOT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n";
